// NASA's Astronomy Picture of the Day, filling the screen, with its title,
// date and credit in a bar along the bottom, and its explanation as a line
// in that bar or as a page beside the picture (Settings: Explanation).
//
// The scene looks for a new picture only when one is due: a new one comes
// out once a day, just after midnight US Eastern, and the frame wakes a few
// minutes after it. What it found last is kept in the scene's state (the
// private `apod` field), so a restart or a failed look still shows it, with
// a note saying what went wrong.
import type { Apod } from './apod'
import { fromApiNasa, fromScience, pickRendition, secondsToNextLook, shouldLook } from './apod'

type Kept = { picture: Apod | null; lookedAt: number; error: string }

const UA = 'FrameOS NASA picture of the day (https://github.com/FrameOS/frameos)'
const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December']

/** The state's record: an object, or its JSON from a saved field. */
export function readKept(value: any): Kept {
  let v = value
  if (typeof v === 'string') {
    try {
      v = JSON.parse(v)
    } catch (e) {
      v = null
    }
  }
  if (!v || typeof v !== 'object') return { picture: null, lookedAt: 0, error: '' }
  const picture = v.picture && typeof v.picture === 'object' && typeof v.picture.image === 'string' ? v.picture : null
  return { picture, lookedAt: Number(v.lookedAt) || 0, error: typeof v.error === 'string' ? v.error : '' }
}

/** "November 28, 2026", or "Nov 28, 2026" where room is short. */
export function dateLabel(date: string, short = false): string {
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(date || '')
  if (!m) return date || ''
  const month = MONTHS[Number(m[2]) - 1] || ''
  return `${short ? month.slice(0, 3) : month} ${Number(m[3])}, ${m[1]}`
}

// Looks for the newest picture: science.nasa.gov, else api.nasa.gov with the
// scene's key (DEMO_KEY without one). The last picture found stays when
// both fail, and the note says why.
function look(app: FrameOSApp, kept: Kept, now: number, big: boolean): Kept {
  let next: Kept
  try {
    let found: Apod
    try {
      found = fromScience()
    } catch (first) {
      try {
        found = fromApiNasa(String(app.state.apiKey || '').trim(), now, big)
      } catch (second) {
        throw new Error(`${first.message}, and ${second.message}`)
      }
    }
    next = { picture: found, lookedAt: now, error: '' }
  } catch (e) {
    next = { picture: kept.picture, lookedAt: now, error: String(e?.message || e) }
  }
  frameos.setState('apod', next)
  return next
}

// ------------------------------------------------------------ the picture

// The picture on screen, kept between renders while the interpreter lives (a
// tap, a layout's clock): fetched again only for another picture or size.
let shown: { key: string; ref: any } | null = null

// How many pixels a kept picture may hold: an ESP32 in color keeps it in two
// bytes a pixel beside its own canvas (a 13.3" panel's 1200x1600 would not fit
// in one block), one in greys less; a Pi has room.
const mostPixels = (app: FrameOSApp) => (!app.frame.embedded ? 4000000 : app.frame.color === false ? 1400000 : 400000)

// Whether a picture of this shape fills a box of that shape without losing
// much: "auto" fills the box then, and shows the whole picture otherwise.
const closeShape = (a: number, b: number) => Math.max(a / b, b / a) <= 1.4

export type Plan = { url: string; width: number; height: number; fill: boolean }

/** What to download and how big to keep it, for a box of bw x bh on the
 * screen (in the panel's own pixels). */
export function planPicture(p: Apod, bw: number, bh: number, fitMode: string, most: number): Plan {
  const ow = p.width
  const oh = p.height
  const known = ow > 0 && oh > 0
  const fill = fitMode === 'fill' || !known || (fitMode !== 'fit' && closeShape(ow / oh, bw / bh))
  let w = bw
  let h = bh
  // How wide the picture is on the screen: covering the box, or inside it;
  // of a shape not known, wide enough for either way round.
  let wide = Math.max(bw, bh)
  if (known) {
    const s = fill ? Math.max(bw / ow, bh / oh) : Math.min(bw / ow, bh / oh)
    wide = ow * s
    if (!fill) {
      w = ow * s
      h = oh * s
    }
  }
  // The smallest size NASA lists that is that wide, as listed.
  const url = pickRendition(p.renditions || [], wide) || p.image
  // Decoded at no more pixels than the frame may keep, nor than the picture has.
  const room = Math.sqrt(most / Math.max(1, w * h)) * 0.999
  if (room < 1) {
    w *= room
    h *= room
  }
  if (known) {
    const s = fill ? Math.max(w / ow, h / oh) : Math.min(w / ow, h / oh)
    if (s > 1) {
      w /= s
      h /= s
    }
  }
  w = Math.max(1, Math.round(w))
  h = Math.max(1, Math.round(h))
  return { url, width: w, height: h, fill }
}

function fetchPicture(plan: Plan): { image: any; error: string } {
  const key = `${plan.url}|${plan.width}x${plan.height}|${plan.fill}`
  if (shown && shown.key === key) return { image: shown.ref, error: '' }
  if (shown) {
    frameos.releaseImage(shown.ref)
    shown = null
  }
  const r = frameos.fetchImage(plan.url, {
    keep: true,
    width: plan.width,
    height: plan.height,
    fit: plan.fill ? 'cover' : 'contain',
    headers: { 'User-Agent': UA },
  })
  if (!r.image) return { image: null, error: String(r.error || 'NASA sent no picture') }
  shown = { key, ref: r.image }
  return { image: r.image, error: '' }
}

// ------------------------------------------------------------ drawing

// Colors: a dark bar over the picture on a screen that shows it see-through;
// solid on e-paper, where a dithered shade would eat the letters. The page
// beside the picture: night blue on a screen, black on white on e-paper.
function looks(app: FrameOSApp) {
  const paper = app.frame.paper === true || app.frame.color === false
  const inks = app.frame.paper === true && app.frame.color !== false
  return {
    band: paper ? 'bg-black' : 'bg-black/60',
    bandText: 'text-white',
    bandSoft: paper ? 'text-white' : 'text-[#d6dbe3]',
    page: paper ? 'bg-white text-black' : 'bg-[#0b1020] text-[#eef1f6]',
    pageSoft: paper ? 'text-black' : 'text-[#9aa5b5]',
    accent: paper ? (inks ? 'text-[#18539a]' : 'text-black') : 'text-[#8ec5ff]',
    rule: paper ? 'bg-black' : 'bg-[#26304a]',
    note: paper ? 'bg-white text-black border-2 border-black' : 'bg-[#7f1d1d]/90 text-white',
    empty: paper ? 'bg-white text-black' : 'bg-[#0b1020] text-[#eef1f6]',
  }
}

// The size of everything, from the panel's: 1 on an 800x480 panel, less on a
// small one, by halves more where a big panel is drawn at its own pixels
// (render scale 1 on a 13.3" e-paper).
function unitOf(W: number, H: number) {
  const short = Math.min(W, H)
  if (short >= 900) return Math.min(3, Math.floor((short / 480) * 2) / 2)
  return Math.max(0.6, Math.min(1, short / 480))
}

// A ringed planet, the scene's icon.
const ICON = 'M12 6.5a5.5 5.5 0 1 1 0 11a5.5 5.5 0 1 1 0-11zM1.66 15.76A11 3.6 -20 1 1 22.34 8.24A11 3.6 -20 1 1 1.66 15.76zM3.92 14.94A8.6 2.2 -20 1 0 20.08 9.06A8.6 2.2 -20 1 0 3.92 14.94z'
const Planet = ({ size }: { size: number }) => (
  <svg className={`w-[${size}px] h-[${size}px]`} viewBox="0 0 24 24">
    <path fill="currentColor" d={ICON} />
  </svg>
)

// A text in the largest of `sizes` that fits w x h; the smallest when none
// does, cut to the lines that fit.
function fitting(text: string, w: number, h: number, sizes: number[]) {
  for (const size of sizes) {
    const lead = Math.round(size * 1.4)
    const tall = frameos.measureText([text], { className: `text-[${size}px] leading-[${lead}px]`, width: Math.max(1, Math.floor(w)) })[0]
    if (tall <= h) return { size, lead, lines: Math.max(1, Math.floor(h / lead)) }
  }
  const size = sizes[sizes.length - 1]
  const lead = Math.round(size * 1.4)
  return { size, lead, lines: Math.max(1, Math.floor(h / lead)) }
}

// How many lines a text takes in a width, at most `most`.
const linesOf = (text: string, className: string, lead: number, width: number, most: number) =>
  Math.max(1, Math.min(most, Math.round(frameos.measureText([text], { className, width: Math.max(1, Math.floor(width)) })[0] / lead)))

// The note over the picture when the last look failed.
function Note({ text, u, c, top, left, width }: any) {
  const size = Math.max(11, Math.round(13 * u))
  return (
    <div className={`absolute top-[${top}px] left-[${left}px] max-w-[${width}px] rounded-[${Math.round(8 * u)}px] px-[${Math.round(10 * u)}px] py-[${Math.round(6 * u)}px] ${c.note}`}>
      <div className={`text-[${size}px] leading-[${Math.round(size * 1.3)}px] line-clamp-2`}>{text}</div>
    </div>
  )
}

/** The bar along the bottom, measured: its type, its lines and its height. */
export function captionPlan(p: Apod, W: number, H: number, u: number, round: boolean, line: boolean) {
  const short = Math.min(W, H)
  const small = short < 360
  const title = Math.max(15, Math.round(26 * u))
  const titleLead = Math.round(title * 1.2)
  const meta = Math.max(11, Math.round(15 * u))
  const metaLead = Math.round(meta * 1.35)
  const body = Math.max(12, Math.round(16 * u))
  const bodyLead = Math.round(body * 1.35)
  const pad = Math.max(8, Math.round(14 * u))
  // On a round panel the words stay in the square inside the circle.
  const side = round ? Math.floor((short / 2 - 12) * Math.SQRT2) : 0
  const insetX = round ? Math.round((W - side) / 2) : pad
  const bottom = round ? Math.round((H - side) / 2) : pad
  const textW = W - insetX * 2
  const titleLines = small || round ? linesOf(p.title, `text-[${title}px] leading-[${titleLead}px] font-bold`, titleLead, textW, 2) : 1
  const explain = line && !!p.explanation && !round
  const bodyLines = explain ? linesOf(p.explanation, `text-[${body}px] leading-[${bodyLead}px]`, bodyLead, textW, 2) : 0
  const facts = [dateLabel(p.date, small || round), p.video ? 'Video still' : '', p.credit ? `Credit: ${p.credit}` : ''].filter(Boolean).join(' · ')
  const top = Math.round(pad * 0.8)
  const gapTitle = Math.round(2 * u)
  const gapBody = Math.round(4 * u)
  const height = top + titleLines * titleLead + gapTitle + metaLead + (bodyLines ? gapBody + bodyLines * bodyLead : 0) + bottom
  return { title, titleLead, titleLines, meta, metaLead, body, bodyLead, bodyLines, top, gapTitle, gapBody, insetX, bottom, round, facts, height }
}

// The bar along the bottom: the title, the date and the credit, and the
// explanation's first lines where it is asked for.
function Caption({ p, W, k, c }: any) {
  return (
    <div className={`absolute left-0 bottom-0 w-[${W}px] flex flex-col ${c.band} ${k.round ? 'text-center' : 'text-left'} pt-[${k.top}px] pb-[${k.bottom}px] px-[${k.insetX}px]`}>
      <div className={`text-[${k.title}px] leading-[${k.titleLead}px] font-bold ${c.bandText} ${k.titleLines > 1 ? `line-clamp-${k.titleLines}` : 'truncate'}`}>{p.title}</div>
      <div className={`text-[${k.meta}px] leading-[${k.metaLead}px] mt-[${k.gapTitle}px] ${c.bandSoft} truncate`}>{k.facts}</div>
      {k.bodyLines ? (
        <div className={`text-[${k.body}px] leading-[${k.bodyLead}px] mt-[${k.gapBody}px] ${c.bandSoft} line-clamp-${k.bodyLines}`}>{p.explanation}</div>
      ) : null}
    </div>
  )
}

// The page beside (or under) the picture: what it is, its title and date, the
// explanation as large as the room lets it be (and no smaller than reads from
// across a room, cut where it must be), and the credit at the end.
function Page({ p, w, h, u, c, problem }: any) {
  const pad = Math.max(12, Math.round(22 * u))
  const inner = w - pad * 2
  const label = Math.max(11, Math.round(13 * u))
  const labelLead = Math.round(label * 1.4)
  const titleSize = Math.max(18, Math.round(30 * u))
  const titleLead = Math.round(titleSize * 1.15)
  const meta = Math.max(12, Math.round(15 * u))
  const metaLead = Math.round(meta * 1.35)
  const gap = Math.round(12 * u)
  const half = Math.round(gap / 2)
  const ruleH = Math.max(1, Math.round(2 * u))
  const titleLines = linesOf(p.title, `text-[${titleSize}px] leading-[${titleLead}px] font-bold`, titleLead, inner, 3)
  const credit = p.credit ? `Credit: ${p.credit}` : ''
  const creditLines = credit ? linesOf(credit, `text-[${meta}px] leading-[${metaLead}px]`, metaLead, inner, 2) : 0
  const problemLines = problem ? linesOf(problem, `text-[${meta}px] leading-[${metaLead}px] font-bold`, metaLead, inner, 3) : 0
  const room =
    h - pad * 2 - (problemLines ? problemLines * metaLead + gap : 0) - labelLead - half - titleLines * titleLead -
    metaLead - (half + ruleH + gap - half) - (creditLines ? gap + creditLines * metaLead : 0)
  const sizes = [22, 21, 20, 19, 18, 17, 16, 15, 14].map((s) => Math.max(13, Math.round(s * u)))
  const body = fitting(p.explanation || '', inner, Math.max(0, room), sizes)
  const bodyLines = Math.min(body.lines, Math.floor(Math.max(0, room) / body.lead))
  return (
    <div className={`flex flex-col w-[${w}px] h-[${h}px] p-[${pad}px] ${c.page}`}>
      {problemLines ? (
        <div className={`text-[${meta}px] leading-[${metaLead}px] mb-[${gap}px] line-clamp-${problemLines} font-bold ${c.accent}`}>{problem}</div>
      ) : null}
      <div className={`text-[${label}px] leading-[${labelLead}px] uppercase font-bold ${c.accent}`}>Astronomy Picture of the Day</div>
      <div className={`text-[${titleSize}px] leading-[${titleLead}px] font-bold mt-[${half}px] line-clamp-${titleLines}`}>{p.title}</div>
      <div className={`text-[${meta}px] leading-[${metaLead}px] ${c.pageSoft}`}>{dateLabel(p.date)}{p.video ? ' · Video still' : ''}</div>
      <div className={`h-[${ruleH}px] w-[${Math.round(48 * u)}px] mt-[${half}px] mb-[${gap - half}px] ${c.rule}`} />
      {bodyLines > 0 && p.explanation ? (
        <div className={`h-[${bodyLines * body.lead}px] overflow-hidden text-[${body.size}px] leading-[${body.lead}px] line-clamp-${bodyLines}`}>{p.explanation}</div>
      ) : null}
      {creditLines ? <div className={`text-[${meta}px] leading-[${metaLead}px] mt-[${gap}px] line-clamp-${creditLines} ${c.pageSoft}`}>{credit}</div> : null}
    </div>
  )
}

// Before there is any picture: what the scene is, and what happened.
function Empty({ W, H, u, c, round, error }: any) {
  const icon = Math.round(Math.max(40, Math.min(120, Math.min(W, H) * 0.2)))
  const title = Math.max(18, Math.round(30 * u))
  const line = Math.max(12, Math.round(16 * u))
  // The words' width: the circle's middle on a round panel.
  const room = Math.round(round ? Math.min(W, H) * 0.72 : Math.min(W - 48 * u, 560 * u))
  return (
    <div className={`flex flex-col items-center justify-center w-[${W}px] h-[${H}px] ${c.empty}`}>
      <div className={c.accent}>
        <Planet size={icon} />
      </div>
      <div className={`text-[${title}px] leading-tight font-bold text-center mt-[${Math.round(12 * u)}px] w-[${room}px]`}>NASA picture of the day</div>
      <div className={`text-[${line}px] leading-snug text-center mt-[${Math.round(8 * u)}px] w-[${room}px] line-clamp-4`}>
        {error ? `Could not get the picture: ${error}.` : 'Looking for today’s picture.'}
      </div>
      {error ? <div className={`text-[${line}px] leading-snug text-center mt-[${Math.round(6 * u)}px] w-[${room}px]`}>Trying again in half an hour.</div> : null}
    </div>
  )
}

export function get(app: FrameOSApp, context: FrameOSContext) {
  const W = context?.imageWidth ?? app.frame.width
  const H = context?.imageHeight ?? app.frame.height
  const scale = app.frame.scale || 1
  const now = Date.now()
  const round = context?.round === true
  const u = unitOf(W, H)
  const c = looks(app)

  let kept = readKept(app.state.apod)
  const big = !app.frame.embedded && Math.max(W, H) * scale >= 1400
  if (shouldLook(kept.picture, kept.lookedAt, now)) kept = look(app, kept, now, big)
  // Wake a few minutes after the next picture comes out, within the scene's
  // own interval.
  const interval = Number(app.state.refreshInterval) || 21600
  const wait = secondsToNextLook(kept.picture, kept.lookedAt, now, interval)
  if (wait < interval) frameos.setNextSleep(wait)

  const p = kept.picture
  if (!p) return <Empty W={W} H={H} u={u} c={c} round={round} error={kept.error} />

  // Where the picture goes: the whole screen, or beside the page (wide) or
  // above it (tall) on a large enough panel, as much of it as the picture's
  // shape asks for.
  const mode = String(app.state.explanation || 'line')
  const fitMode = String(app.state.fit || 'auto')
  const paged = mode === 'page' && !round && Math.min(W, H) >= 400
  const wide = W >= H
  const aspect = p.width > 0 && p.height > 0 ? p.width / p.height : 0
  const share = (v: number, lo: number, hi: number) => Math.max(lo, Math.min(hi, v))
  let box = { w: W, h: H }
  if (paged && wide) box = { w: Math.round(W * share(aspect ? (aspect * H) / W : 0.58, 0.42, 0.62)), h: H }
  if (paged && !wide) box = { w: W, h: Math.round(H * share(aspect ? W / aspect / H : 0.5, 0.4, 0.5)) }
  const most = mostPixels(app)
  let plan = planPicture(p, Math.round(box.w * scale), Math.round(box.h * scale), fitMode, most)
  const caption = paged ? null : captionPlan(p, W, H, u, round, mode !== 'off')
  // A picture shown whole goes above the bar where that costs it little of
  // its size (a tall screen), so the bar covers none of it.
  let resting = false
  if (caption && !plan.fill && aspect && !round) {
    const above = H - caption.height
    if (above > 0 && Math.min(W / aspect, above) >= 0.85 * Math.min(W / aspect, H)) {
      box = { w: W, h: above }
      plan = planPicture(p, Math.round(W * scale), Math.round(above * scale), 'fit', most)
      resting = true
    }
  }
  const photo = fetchPicture(plan)
  const stale = kept.error ? `No new picture: ${kept.error}. Showing ${dateLabel(p.date, true)}.` : ''

  // The picture did not come: its words fill the screen, saying why.
  if (!photo.image) {
    const why = /^\d{3}$/.test(photo.error) ? `NASA answered HTTP ${photo.error}` : photo.error
    return <Page p={p} w={W} h={H} u={u} c={c} problem={`The picture did not load: ${why}. Trying again at the next refresh.`} />
  }
  // A picture that fills covers its box; one shown whole sits in the middle
  // of it, or on the bar when it rests above it.
  let place = { x: 0, y: 0, w: box.w, h: box.h }
  if (!plan.fill && aspect) {
    const w = Math.round(Math.min(box.w, box.h * aspect))
    const h = Math.round(w / aspect)
    place = { x: Math.round((box.w - w) / 2), y: resting ? box.h - h : Math.round((box.h - h) / 2), w, h }
  }
  const picture = (
    <img className={`absolute left-[${place.x}px] top-[${place.y}px] w-[${place.w}px] h-[${place.h}px] ${plan.fill ? 'object-cover' : 'object-contain'}`} src={photo.image} />
  )
  const pad = Math.max(8, Math.round(14 * u))
  const noteW = round ? Math.round(Math.min(W, H) * 0.62) : Math.round(Math.min(box.w - pad * 2, 520 * u))
  const noteTop = round ? Math.round(Math.min(W, H) * 0.16) : pad
  const noteLeft = round ? Math.round((W - noteW) / 2) : pad
  const note = stale ? <Note text={stale} u={u} c={c} top={noteTop} left={noteLeft} width={noteW} /> : null

  if (paged) {
    return (
      <div className={`relative w-[${W}px] h-[${H}px] bg-black`}>
        {picture}
        <div className={`absolute ${wide ? `left-[${box.w}px] top-0` : `left-0 top-[${box.h}px]`}`}>
          <Page p={p} w={wide ? W - box.w : W} h={wide ? H : H - box.h} u={u} c={c} />
        </div>
        {note}
      </div>
    )
  }
  return (
    <div className={`relative w-[${W}px] h-[${H}px] bg-black`}>
      {picture}
      <Caption p={p} W={W} k={caption} c={c} />
      {note}
    </div>
  )
}

