// Where the picture of the day comes from, and when the next one is due.
//
// The Astronomy Picture of the Day lives on science.nasa.gov now: each day is
// a post of its WordPress site, in the APOD category, with the picture, its
// title, the explanation and the credit. One request for the newest, its
// fields cut to what the scene shows (about 16 KB). api.nasa.gov's APOD
// endpoint is the fallback when that site cannot be reached. Since APOD moved,
// it answers every recent day with the NASA logo and the title "NASA
// Science", which is no picture, so such an answer is skipped.
//
// The picture is downloaded as NASA publishes it, straight from NASA: one of
// the sizes the post itself lists for its picture (its srcset, the same list
// as the WordPress media sizes), the smallest at least as large as the frame
// draws it, never an address the scene makes up. The frame's decoder fits it
// to the screen as it streams in.

/** A size of the picture the post lists: its address as listed, and its width (0 when not said). */
export type Rendition = { url: string; w: number }

export type Apod = {
  date: string // "2026-11-28": the day it is the picture of (US Eastern)
  published: number // when it came out (ms): the next one comes a day later
  title: string
  explanation: string
  credit: string
  image: string // the picture as published: the largest size listed, or api.nasa.gov's url (hdurl on a big screen)
  renditions: Rendition[] // the sizes listed, smallest first (empty: only `image`)
  width: number // its shape, 0 when not known
  height: number
  hd?: string // api.nasa.gov's hdurl
  video?: boolean // a video's day, shown by its still
  link: string
  source: 'science.nasa.gov' | 'api.nasa.gov'
}

const HOUR = 3600 * 1000
const DAY = 24 * HOUR
// A new picture comes out at 00:05 US Eastern; look a little after.
const SLACK = 10 * 60 * 1000
// After a failed or early look, the next one no sooner than this.
export const RETRY_MS = 30 * 60 * 1000

const UA = 'FrameOS NASA picture of the day (https://github.com/FrameOS/frameos)'
const SCIENCE = 'https://science.nasa.gov/wp-json/wp/v2/image-article'
// The APOD category of science.nasa.gov's posts.
const CATEGORY = 22766
const FIELDS = 'id,date,date_gmt,link,title,content,featured_image_url,featured_media'
const MEDIA = 'https://science.nasa.gov/wp-json/wp/v2/media'

// ------------------------------------------------------------ text from HTML

const NAMED: Record<string, string> = {
  amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ', hellip: '…', ndash: '–', mdash: '—',
  lsquo: '‘', rsquo: '’', ldquo: '“', rdquo: '”', deg: '°', times: '×', eacute: 'é', copy: '©',
}

/** HTML's entities as the characters they stand for. */
export function decode(text: string): string {
  return String(text || '').replace(/&(#x[0-9a-f]+|#\d+|[a-z]+);/gi, (whole, name) => {
    if (name[0] === '#') {
      const code = name[1] === 'x' || name[1] === 'X' ? parseInt(name.slice(2), 16) : parseInt(name.slice(1), 10)
      return code > 0 && code < 0x110000 ? String.fromCodePoint(code) : whole
    }
    return NAMED[name.toLowerCase()] ?? whole
  })
}

/** Markup as plain text: tags gone, entities decoded, white space one space. */
export function plain(html: string): string {
  return decode(String(html || '').replace(/<[^>]*>/g, ' '))
    .replace(/\s+/g, ' ')
    .replace(/\s+([,.;:!?)\]’”])/g, '$1')
    .replace(/([(\[“‘])\s+/g, '$1')
    .trim()
}

// ------------------------------------------------------------ science.nasa.gov

const attr = (tag: string, name: string) => {
  const m = new RegExp(`\\s${name}="([^"]*)"`).exec(tag)
  return m ? decode(m[1]) : ''
}

const isPicture = (url: string) => /^https?:\/\/\S+$/.test(url)

/** The sizes an <img>'s srcset lists ("<url> 950w, ..."), as listed, smallest first. */
export function renditionsOf(srcset: string): Rendition[] {
  const seen: Record<string, boolean> = {}
  const out: Rendition[] = []
  for (const m of String(srcset || '').matchAll(/(\S+)\s+(\d+)w/g)) {
    const url = m[1].replace(/^,/, '')
    if (!isPicture(url) || seen[url]) continue
    seen[url] = true
    out.push({ url, w: Number(m[2]) })
  }
  return out.sort((a, b) => a.w - b.w)
}

/** The smallest listed size at least `need` pixels wide, else the largest. */
export function pickRendition(renditions: Rendition[], need: number): string {
  const sized = renditions.filter((r) => r.w > 0)
  if (!sized.length) return renditions.length ? renditions[renditions.length - 1].url : ''
  return (sized.find((r) => r.w >= need * 0.98) ?? sized[sized.length - 1]).url
}

// The top of a post: its picture (or video), up to its title.
function heroOf(html: string): string {
  const at = html.indexOf('media-detail-hero__media')
  if (at < 0) return ''
  const hero = html.slice(at, at + 16000)
  const ends = [hero.indexOf('</figure>'), hero.indexOf('<h1')].filter((i) => i > 0)
  return ends.length ? hero.slice(0, Math.min(...ends)) : hero
}

/** Whether a post shows a video, or anything but an <img>, at its top: its
 * picture's sizes are then only in its media entry. */
export const needsMedia = (post: any) => !/<img\s/.test(heroOf(String(post?.content?.rendered || '')))

// A picture on NASA's other store (.../jcr:content/renditions/...) is listed
// at the box (1280x1280) its sizes fit in, not at its own shape.
const boxedAt = (url: string) => /\/jcr:content\/renditions\//.test(url)

/** The sizes a WordPress media entry lists for a picture (media_details.sizes
 * and the original), as listed, smallest first, and the picture's shape. */
export function fromMedia(media: any): { renditions: Rendition[]; width: number; height: number } {
  const md = media && typeof media.media_details === 'object' && media.media_details ? media.media_details : {}
  const all: Rendition[] = Object.values(md.sizes || {}).map((s: any) => ({ url: String(s?.source_url || ''), w: Number(s?.width) || 0 }))
  if (typeof media?.source_url === 'string') all.push({ url: media.source_url, w: Number(md.width) || 0 })
  const seen: Record<string, boolean> = {}
  // A 48 px "full" (NASA's other store lists one) is no size to show.
  const renditions: Rendition[] = []
  for (const r of all) {
    if (!isPicture(r.url) || /thumbnail\.48\.48/.test(r.url) || seen[r.url]) continue
    seen[r.url] = true
    renditions.push(r)
  }
  renditions.sort((a, b) => a.w - b.w)
  const boxed = renditions.some((r) => boxedAt(r.url))
  return { renditions, width: boxed ? 0 : Number(md.width) || 0, height: boxed ? 0 : Number(md.height) || 0 }
}

/** A science.nasa.gov APOD post as the scene keeps it, or null when it holds
 * no picture. `media` is its featured media entry, for a post that shows no
 * <img> at its top (a video's day). */
export function fromPost(post: any, media?: any): Apod | null {
  const html = String(post?.content?.rendered || '')
  // The picture: the image at the post's top, with the sizes it lists; else
  // the sizes its media entry lists; else its featured image as it is.
  const heroMedia = heroOf(html)
  const tag = /<img\s[^>]*>/.exec(heroMedia)?.[0] ?? ''
  const src = attr(tag, 'src')
  let renditions = renditionsOf(attr(tag, 'srcset'))
  if (!renditions.length && isPicture(src)) renditions = [{ url: src, w: Number(attr(tag, 'width')) || 0 }]
  // Its shape: the tag's size, except on NASA's other store.
  let width = boxedAt(src) ? 0 : Number(attr(tag, 'width')) || 0
  let height = boxedAt(src) ? 0 : Number(attr(tag, 'height')) || 0
  if (!renditions.length && media) ({ renditions, width, height } = fromMedia(media))
  const featured = typeof post?.featured_image_url === 'string' ? post.featured_image_url : ''
  // A featured image of 48 px (some days list only that) is no picture to show.
  if (!renditions.length && isPicture(featured) && !/thumbnail\.48\.48/.test(featured)) renditions = [{ url: featured, w: 0 }]
  if (!renditions.length) return null

  // The title without "APOD: 2026 November 28 – ".
  const title =
    decode(String(post?.title?.rendered || '')).replace(/^APOD:\s*\d{4}\s+[A-Za-z]+\s+\d{1,2}\s*[–—-]\s*/, '').trim() ||
    plain(/<h1[^>]*>([\s\S]*?)<\/h1>/.exec(html)?.[1] ?? '')
  const explained = /Explanation:\s*<\/strong>([\s\S]*?)<\/p>/.exec(html)?.[1] ?? ''
  const explanation = plain(explained).replace(/\s*Tomorrow['’]s picture:.*$/i, '').trim()
  const credited = /<th[^>]*>([^<]*Credit[^<]*)<\/th>\s*<td[^>]*>([\s\S]*?)<\/td>/i.exec(html)
  const credit = credited ? plain(credited[2]) : ''
  const date = String(post?.date || '').slice(0, 10)
  const gmt = Date.parse(String(post?.date_gmt || '') + 'Z')
  return {
    date,
    published: Number.isFinite(gmt) ? gmt : publishedOf(date),
    title: title || 'Astronomy Picture of the Day',
    explanation,
    credit,
    image: renditions[renditions.length - 1].url,
    renditions,
    width,
    height,
    video: /<iframe|<video/i.test(heroMedia) || undefined,
    link: typeof post?.link === 'string' ? post.link : 'https://science.nasa.gov/apod/',
    source: 'science.nasa.gov',
  }
}

function getJson(url: string, headers: Record<string, string>, what: string) {
  const r = frameos.httpRequest(url, { headers: { Accept: 'application/json', 'User-Agent': UA, ...headers }, timeoutMs: 20000 })
  if (!r.status) throw new Error(`${what} did not answer${r.error ? `: ${r.error}` : ''}`)
  if (r.status === 429) throw new Error(`${what} says too many requests`)
  if (r.status >= 400) throw new Error(`${what} answered HTTP ${r.status}`)
  try {
    return JSON.parse(r.body || '')
  } catch (e) {
    throw new Error(`${what} sent something that is not JSON`)
  }
}

/** The newest APOD with a picture, from science.nasa.gov. */
export function fromScience(): Apod {
  const posts = getJson(`${SCIENCE}?categories=${CATEGORY}&per_page=1&_fields=${FIELDS}`, {}, 'science.nasa.gov')
  if (!Array.isArray(posts) || posts.length === 0) throw new Error('science.nasa.gov lists no picture of the day')
  const newest = withMedia(posts[0])
  if (newest) return newest
  // A day without a picture: the newest of the last week that has one.
  const week = getJson(`${SCIENCE}?categories=${CATEGORY}&per_page=7&_fields=id,featured_image_url`, {}, 'science.nasa.gov')
  const day = (Array.isArray(week) ? week : [])
    .slice(1)
    .find((p: any) => p && isPicture(String(p.featured_image_url || '')) && !/thumbnail\.48\.48/.test(p.featured_image_url))
  if (!day) throw new Error('science.nasa.gov has no picture this week')
  const post = getJson(`${SCIENCE}/${Number(day.id)}?_fields=${FIELDS}`, {}, 'science.nasa.gov')
  const found = withMedia(post)
  if (!found) throw new Error('science.nasa.gov has no picture this week')
  return found
}

// A post that shows no <img> at its top (a video's day): its picture's sizes
// from its media entry, one more request (about 8 KB).
function withMedia(post: any): Apod | null {
  const id = Number(post?.featured_media)
  let media
  if (needsMedia(post) && id > 0) {
    try {
      media = getJson(`${MEDIA}/${id}?_fields=source_url,media_details`, {}, 'science.nasa.gov')
    } catch (e) {
      media = undefined
    }
  }
  return fromPost(post, media)
}

// ------------------------------------------------------------ api.nasa.gov

// When a day's picture came out: 00:05 US Eastern, taken as 05:05 UTC (an
// hour late in summer, which only makes the frame look an hour later).
const publishedOf = (date: string) => {
  const t = Date.parse(`${date}T05:05:00Z`)
  return Number.isFinite(t) ? t : 0
}

// The day it is in US Eastern time, give or take the summer hour.
const easternDay = (now: number, back = 0) => new Date(now - 5 * HOUR - back * DAY).toISOString().slice(0, 10)

/** An api.nasa.gov answer as the scene keeps it, or null when it holds no picture. */
export function fromApi(entry: any, big: boolean): Apod | null {
  if (!entry || typeof entry !== 'object') return null
  const video = entry.media_type === 'video'
  const url = String((video ? entry.thumbnail_url : entry.url) || '')
  // Since APOD moved, the API answers recent days with the NASA logo.
  if (!/^https?:\/\//.test(url) || /nasa-logo/i.test(url) || String(entry.title || '').trim() === 'NASA Science') return null
  if (!video && entry.media_type && entry.media_type !== 'image') return null
  if (!/\.(jpe?g|png|gif|webp)(\?|$)/i.test(url) && !video) return null
  const hd = !video && typeof entry.hdurl === 'string' ? entry.hdurl : undefined
  const date = String(entry.date || '').slice(0, 10)
  return {
    date,
    published: publishedOf(date),
    title: String(entry.title || 'Astronomy Picture of the Day').trim(),
    explanation: String(entry.explanation || '').replace(/\s*Tomorrow['’]s picture:.*$/is, '').replace(/\s+/g, ' ').trim(),
    credit: String(entry.copyright || '').replace(/\s+/g, ' ').trim(),
    image: big && hd ? hd : url,
    renditions: [],
    width: 0,
    height: 0,
    hd,
    video: video || undefined,
    link: `https://apod.nasa.gov/apod/ap${date.slice(2).replace(/-/g, '')}.html`,
    source: 'api.nasa.gov',
  }
}

/** The newest APOD with a picture from api.nasa.gov: the last eight days in one request. */
export function fromApiNasa(key: string, now: number, big: boolean): Apod {
  const k = encodeURIComponent(key || 'DEMO_KEY')
  const what = 'api.nasa.gov'
  let days
  try {
    days = getJson(`https://api.nasa.gov/planetary/apod?api_key=${k}&thumbs=true&start_date=${easternDay(now, 7)}`, {}, what)
  } catch (e) {
    const message = String(e?.message || e)
    if (/too many/.test(message)) throw new Error(`${what} says too many requests: add your own NASA API key in the settings`)
    if (/HTTP 40[13]/.test(message)) throw new Error(`${what} refused the API key`)
    // A day it cannot read answers 500 for the whole range (today's, on
    // 2026-11-28): ask for the week before it.
    if (!/HTTP 5\d\d/.test(message)) throw e
    days = getJson(`https://api.nasa.gov/planetary/apod?api_key=${k}&thumbs=true&start_date=${easternDay(now, 8)}&end_date=${easternDay(now, 1)}`, {}, what)
  }
  const list = (Array.isArray(days) ? days : [days]).slice().reverse()
  for (const entry of list) {
    const found = fromApi(entry, big)
    if (found) return found
  }
  throw new Error(`${what} has no picture for the last week`)
}

// ------------------------------------------------------------ when

/** When the next picture should be out: a day after this one, a little late. */
export const nextDue = (apod: Apod | null) => (apod && apod.published ? apod.published + DAY + SLACK : 0)

/** Whether to look for a new picture now: there is none, or the next one is
 * due; never sooner than RETRY_MS after the last look that found nothing new
 * or failed. */
export function shouldLook(apod: Apod | null, lookedAt: number, now: number): boolean {
  if (lookedAt && now - lookedAt < RETRY_MS && now >= lookedAt) return false
  if (!apod) return true
  return now >= nextDue(apod)
}

/** Seconds until the scene should look again, at most `cap`. */
export function secondsToNextLook(apod: Apod | null, lookedAt: number, now: number, cap: number): number {
  let at = Math.max(nextDue(apod), lookedAt ? lookedAt + RETRY_MS : 0)
  if (!apod) at = (lookedAt || now) + RETRY_MS
  if (at <= now) at = now + RETRY_MS
  return Math.max(60, Math.min(cap, Math.ceil((at - now) / 1000)))
}

