// api.nasa.gov's answer for a range of days, shaped as it is: since APOD
// moved, recent days come back as the NASA logo titled "NASA Science".
const logo = (date: string) => ({
  date,
  explanation: 'Something.',
  hdurl: 'https://science.nasa.gov/wp-content/themes/nasa-child/assets/images/nasa-logo@2x.png',
  media_type: 'image',
  service_version: 'v1',
  title: 'NASA Science',
  url: 'https://science.nasa.gov/wp-content/themes/nasa-child/assets/images/nasa-logo@2x.png',
})

const NOW = Date.UTC(2026, 10, 28, 15, 0, 0) // 2026-11-28 15:00 UTC
const PUBLISHED = Date.UTC(2026, 10, 28, 5, 5, 0)
const HOUR = 3600 * 1000

function at<T>(when: number, run: () => T): T {
  const real = Date.now
  Date.now = () => when
  try {
    return run()
  } finally {
    Date.now = real
  }
}

// Every text a UI draws, function components run, in order.
function texts(node: any): string[] {
  if (node === null || node === undefined || node === false || node === true) return []
  if (typeof node === 'string' || typeof node === 'number') return [String(node)]
  if (Array.isArray(node)) return node.flatMap(texts)
  if (typeof node.type === 'function') return texts(node.type(node.props || {}))
  return texts(node.props?.children)
}
const shown = (node: any) => texts(node).join(' ')
// The <img> elements of a UI.
function images(node: any): any[] {
  if (!node || typeof node !== 'object') return []
  if (Array.isArray(node)) return node.flatMap(images)
  if (typeof node.type === 'function') return images(node.type(node.props || {}))
  const own = node.type === 'img' ? [node] : []
  return own.concat(images(node.props?.children))
}

function nasa(routes: { science?: (url: string) => any; api?: (url: string) => any }) {
  return mock.httpRequest((url: string) => {
    if (url.startsWith('https://science.nasa.gov/')) return routes.science ? routes.science(url) : mock.response(503, 'down')
    if (url.startsWith('https://api.nasa.gov/')) return routes.api ? routes.api(url) : mock.response(503, 'down')
    return mock.response(404, '')
  })
}

