    expect(p.video).toBe(true)
  })

  it('takes a video day’s still from its media entry, at the sizes it lists', () => {
    const p = fromPost(SPHEREX_POST, SPHEREX_MEDIA)
    expect(needsMedia(SPHEREX_POST)).toBe(true)
    expect(needsMedia(post())).toBe(false)
    expect(p).toMatchObject({ title: 'SPHEREx Seeing Through Dust', video: true, width: 3274, height: 2040, image: PNG })
    expect(p.renditions.map((r) => r.w)).toEqual([150, 600, 900, 1536, 3274, 3274])
    // As wide as an 800x480 screen: the 900 px size, not the 11.7 MB original.
    expect(planPicture(p, 800, 480, 'auto', 4000000).url).toBe(`${PNG}?w=900&h=900&fit=clip`)
  })

  it('is no picture without one, nor with only a 48 px one', () => {
    expect(fromPost(post({ content: { rendered: '<p><strong>Explanation:</strong> Words.</p>' }, featured_image_url: '' }))).toBe(null)
