describe('when to look', () => {
  it('looks when there is nothing, and a few minutes after the next one is out', () => {
    const p = fromPost(post())
    expect(shouldLook(null, 0, NOW)).toBe(true)
    expect(shouldLook(p, NOW - 2 * HOUR, NOW)).toBe(false)
    expect(nextDue(p)).toBe(PUBLISHED + 24 * HOUR + 10 * 60 * 1000)
    expect(shouldLook(p, NOW, nextDue(p))).toBe(true)
    // Not again within half an hour of the last look.
    expect(shouldLook(p, nextDue(p), nextDue(p) + 10 * 60 * 1000)).toBe(false)
    expect(secondsToNextLook(p, NOW, NOW, 86400)).toBe((nextDue(p) - NOW) / 1000)
    expect(secondsToNextLook(p, NOW, NOW, 21600)).toBe(21600)
  })
})

describe('the picture asked for', () => {
  const listed = LISTED.map(([url]) => url)

  it('downloads the smallest size listed that is as large as the picture is drawn, never a size of its own', () => {
    const p = fromPost(post())
    // Whole on an 800x480 LCD: 445 px wide, so the 556 px size.
    expect(planPicture(p, 800, 480, 'auto', 4000000)).toEqual({ url: `${DYN}?w=600&h=600&fit=clip`, width: 445, height: 480, fill: false })
    // Filling a 13.3" e-paper at its own pixels: 1484 px wide, so the 1568 px size.
    expect(planPicture(p, 1200, 1600, 'auto', 4000000)).toEqual({ url: `${DYN}?w=1568&h=2172&fit=clip`, width: 1200, height: 1600, fill: true })
    // Wider than every listed size: the largest, the original.
    expect(planPicture(p, 4000, 4000, 'fit', 40000000).url).toBe(DYN)
    for (const [w, h] of [[240, 320], [466, 466], [480, 800], [800, 480], [1872, 1404]]) {
      for (const fit of ['auto', 'fill', 'fit']) expect(listed.includes(planPicture(p, w, h, fit, 4000000).url)).toBe(true)
    }
  })

  it('decodes no more pixels than the frame keeps, whatever it downloads', () => {
    const big = planPicture(fromPost(post()), 1200, 1600, 'fill', 400000)
    expect(big.url).toBe(`${DYN}?w=1568&h=2172&fit=clip`)
    expect(big.width * big.height <= 400000).toBe(true)
    expect(big.fill).toBe(true)
  })
})

describe('the scene', () => {
  it('fetches the newest picture, keeps it, and draws its title, date and credit', () => {
    const http = nasa({ science: () => mock.json([post()]) })
    const fetchImage = mock.fetchImage(() => mock.image({ width: 445, height: 480 }))
    mock.releaseImage(() => true)
    const app = makeApp({ state: {} })
    const ui = at(NOW, () => get(app, makeContext()))
    expect(http.calls.length).toBe(1)
    expect(http.calls[0][0]).toContain('categories=22766&per_page=1')
    expect(fetchImage.calls[0][0]).toBe(`${DYN}?w=600&h=600&fit=clip`)
    expect(fetchImage.calls[0][1]).toMatchObject({ keep: true, width: 445, height: 480 })
    expect(readKept(app.state.apod)).toMatchObject({ lookedAt: NOW, error: '', picture: { title: 'Apollo 17 VIP Site Anaglyph' } })
    const words = shown(ui)
    expect(words).toContain('Apollo 17 VIP Site Anaglyph')
    expect(words).toContain('November 28, 2026')
    expect(words).toContain('Credit: Gene Cernan')
    expect(images(ui).length).toBe(1)
  })

  it('asks a video day’s media entry for its still’s sizes, and downloads one as listed', () => {
    const http = nasa({ science: (url) => (url.includes('/media/1517733') ? mock.json(SPHEREX_MEDIA) : mock.json([SPHEREX_POST])) })
    const fetchImage = mock.fetchImage(() => mock.image({ width: 800, height: 480 }))
    mock.releaseImage(() => true)
    const app = makeApp({ state: {}, frame: { width: 800, height: 480 } })
    const words = shown(at(NOW, () => get(app, makeContext())))
    expect(http.calls.map((c) => c[0].split('?')[0])).toEqual([
      'https://science.nasa.gov/wp-json/wp/v2/image-article',
      'https://science.nasa.gov/wp-json/wp/v2/media/1517733',
    ])
    expect(fetchImage.calls[0][0]).toBe(`${PNG}?w=900&h=900&fit=clip`)
    expect(words).toContain('Video still')
  })

  it('does not look again before the next picture is due, and wakes for it', () => {
    const http = nasa({ science: () => mock.json([post()]) })
    mock.fetchImage(() => mock.image())
    mock.releaseImage(() => true)
    const app = makeApp({ state: {} })
    at(NOW, () => get(app, makeContext()))
    at(NOW + 6 * HOUR, () => get(app, makeContext()))
    expect(http.calls.length).toBe(1)
    // At midnight UTC the next picture, at 05:15, is within the interval: the frame wakes for it.
    const late = NOW + 9 * HOUR
    at(late, () => get(app, makeContext()))
    expect(app.nextSleep).toBe((nextDue(fromPost(post())) - late) / 1000)
    at(nextDue(fromPost(post())) + 1000, () => get(app, makeContext()))
    expect(http.calls.length).toBe(2)
  })

  it('asks api.nasa.gov when science.nasa.gov is down, past the days it answers with the logo', () => {
    const http = nasa({
      api: () =>
        mock.json([
          { date: '2026-11-20', title: 'Old moon', explanation: 'Words.', media_type: 'image', url: 'https://apod.nasa.gov/apod/image/2611/moon_1024.jpg', copyright: 'Ann' },
          logo('2026-11-27'),
          logo('2026-11-28'),
        ]),
    })
    mock.fetchImage(() => mock.image())
    mock.releaseImage(() => true)
    const app = makeApp({ state: { apiKey: ' my-key ' } })
    const ui = at(NOW, () => get(app, makeContext()))
    expect(http.calls[1][0]).toContain('api_key=my-key&thumbs=true&start_date=2026-11-21')
    expect(readKept(app.state.apod).picture).toMatchObject({ title: 'Old moon', source: 'api.nasa.gov', image: 'https://apod.nasa.gov/apod/image/2611/moon_1024.jpg' })
    expect(shown(ui)).toContain('Old moon')
  })

  it('keeps the last picture when both fail, says why, and waits before trying again', () => {
    const http = nasa({ api: () => mock.response(429, 'OVER_RATE_LIMIT') })
    mock.fetchImage(() => mock.image())
    mock.releaseImage(() => true)
    const before = { picture: fromPost(post({ date: '2026-11-27T00:05:00', date_gmt: '2026-11-27T05:05:00' })), lookedAt: NOW - 20 * HOUR, error: '' }
    const app = makeApp({ state: { apod: before } })
    const ui = at(NOW, () => get(app, makeContext()))
    const kept = readKept(app.state.apod)
    expect(kept.picture.date).toBe('2026-11-27')
    expect(kept.error).toBe('science.nasa.gov answered HTTP 503, and api.nasa.gov says too many requests: add your own NASA API key in the settings')
    expect(shown(ui)).toContain('No new picture: science.nasa.gov answered HTTP 503')
    expect(shown(ui)).toContain('Showing Nov 27, 2026')
    expect(app.nextSleep).toBe(1800)
    const calls = http.calls.length
    at(NOW + 10 * 60 * 1000, () => get(app, makeContext()))
    expect(http.calls.length).toBe(calls)
  })

  it('says what happened when there is no picture yet', () => {
    nasa({ science: () => ({ status: 0, error: 'no network' }), api: () => ({ status: 0, error: 'no network' }) })
    const app = makeApp({ state: {} })
    const ui = at(NOW, () => get(app, makeContext()))
    expect(shown(ui)).toContain('Could not get the picture: science.nasa.gov did not answer: no network')
    expect(shown(ui)).toContain('Trying again in half an hour.')
  })

  it('shows the words when the picture does not load', () => {
    nasa({ science: () => mock.json([post()]) })
    mock.fetchImage(() => ({ image: null, error: '404' }))
    mock.releaseImage(() => true)
    // A panel of another size: the picture kept for the tests before is not this one.
    const app = makeApp({ state: {}, frame: { width: 640, height: 400 } })
    const ui = at(NOW, () => get(app, makeContext()))
    expect(shown(ui)).toContain('The picture did not load: NASA answered HTTP 404')
    expect(shown(ui)).toContain('Get out your red/blue glasses')
    expect(images(ui).length).toBe(0)
  })

  it('puts the explanation on a page beside the picture where asked, and leaves it out where not', () => {
    nasa({ science: () => mock.json([post()]) })
    mock.fetchImage(() => mock.image())
    mock.releaseImage(() => true)
    const paged = makeApp({ state: { explanation: 'page' } })
    const page = shown(at(NOW, () => get(paged, makeContext())))
    expect(page).toContain('Astronomy Picture of the Day')
    expect(page).toContain('Taurus-Littrow')
    const off = makeApp({ state: { explanation: 'off', apod: paged.state.apod } })
    expect(shown(at(NOW, () => get(off, makeContext())))).not.toContain('Taurus-Littrow')
  })
})
